def _build() -> List[Dict[str, Any]]:
    temples = []
    for slug, hi, en, sevas in _ROWS:
        offerings = []
        for category, price, prasad, hi_s, en_s in sevas:
            offerings.append({
                "title": hi_s[0], "description": hi_s[1], "category": category, "price": float(price),
                "has_prasad_delivery": prasad, "delivery_fee": 99.0 if prasad else 0.0, "includes_video_proof": True,
            })
        temples.append({
            "name": hi[0], "slug": slug, "deity": hi[1], "city": hi[2], "state": hi[3],
            "description": hi[4], "history_significance": hi[5],
            "image_url": f"/assets/img/temples/{slug}.jpg", "banner_url": f"/assets/img/temples/{slug}.jpg",
            "live_status": "बुकिंग उपलब्ध", "offerings": offerings,
        })
        catalog_i18n.TEMPLES_EN[slug] = {"name": en[0], "deity": en[1], "city": en[2], "state": en[3], "description": en[4]}
        catalog_i18n.OFFERINGS_EN[slug] = [s[4] for s in sevas]
    return temples


